content:
{%- set company = doc.get("company") or frappe.db.get_default("company") -%}
{%- set c = frappe.db.get_value("Company", company, "*", as_dict=True) if company else None -%}
{%- if c -%}
{%- set address_name = doc.get("company_address") or doc.get("billing_address") -%}
{%- if not address_name -%}
{%- set address_name = (frappe.get_all("Address", filters=[["Dynamic Link", "link_doctype", "=", "Company"], ["Dynamic Link", "link_name", "=", company], ["disabled", "=", 0]], order_by="is_primary_address desc, creation asc", pluck="name", limit=1) or [None])[0] -%}
{%- endif -%}
{%- set a = (frappe.db.get_value("Address", address_name, "*", as_dict=True) if address_name else None) or {} -%}
{%- set street = [a.get("address_line1"), a.get("address_line2")] | select | join(", ") -%}
{%- set place = [([a.get("city"), a.get("pincode")] | select | join(" - ")), a.get("state"), a.get("country") if a.get("country") != c.country else ""] | select | join(", ") -%}
{%- set tax_label, tax_value = (_("GSTIN"), a.gstin) if a.get("gstin") else (_("Tax ID"), c.tax_id) -%}
{%- set website = (c.website or "").replace("https://", "").replace("http://", "").rstrip("/") -%}
{%- set contacts = [a.get("phone") or c.phone_no, [a.get("email_id") or c.email, website] | select | join(" · ")] | select | list -%}
{%- set ids = [(tax_label, tax_value) if tax_value else none, (_("PAN"), c.pan) if c.get("pan") else none] | select | list -%}
<table class="company-letterhead">
	<tr>
		<td class="company-letterhead-logo">{%- if c.company_logo %}<img src="{{ frappe.utils.get_url(c.company_logo) }}" alt="{{ c.company_name | e }}">{% endif -%}</td>
		<td class="company-letterhead-company">
			<div class="company-letterhead-name">{{ c.company_name | e }}</div>
			{%- if street %}<div class="company-letterhead-line">{{ street | e }}</div>{% endif %}
			{%- if place %}<div class="company-letterhead-line">{{ place | e }}</div>{% endif %}
		</td>
		<td class="company-letterhead-ids">
			{%- for label, value in ids %}<div class="company-letterhead-line"><span class="company-letterhead-label">{{ label }}</span> {{ value | e }}</div>{% endfor %}
			{%- for value in contacts %}<div class="company-letterhead-line">{{ value | e }}</div>{% endfor %}
		</td>
	</tr>
</table>
{%- endif -%}

custom_css:
.letter-head .company-letterhead { width: 100%; border-collapse: collapse; border-bottom: 1px solid #e5e7eb; font-family: Inter, sans-serif; color: #1f2328; }
.letter-head .company-letterhead td { padding: 0 0 8px; vertical-align: middle; }
.letter-head .company-letterhead .company-letterhead-logo { width: 0; padding: 0 0 8px; }
.letter-head .company-letterhead .company-letterhead-company { width: 60%; }
.letter-head .company-letterhead .company-letterhead-logo img { display: block; width: auto; height: auto; max-width: 120px; max-height: 46px; margin-right: 12px; }
.letter-head .company-letterhead .company-letterhead-ids { padding-left: 24px; text-align: right; }
.letter-head .company-letterhead .company-letterhead-ids .company-letterhead-line { white-space: nowrap; }
.letter-head .company-letterhead .company-letterhead-name { font-size: 16px; line-height: 20px; font-weight: 700; }
.letter-head .company-letterhead .company-letterhead-line { margin-top: 1px; font-size: 11px; line-height: 15px; color: #374151; }
.letter-head .company-letterhead .company-letterhead-label { color: #6b7280; }
